package dev.fluidgore.blood;

import dev.fluidgore.config.BloodStyle;
import dev.fluidgore.config.GoreConfig;
import net.minecraft.resources.Identifier;
import net.minecraft.util.RandomSource;

/**
 * The blood atlas ({@code assets/fluidgore/textures/misc/blood.png}) is a 4x4 grid of 64px white/grey shapes.
 * The colour comes from the vertex colour, so one texture serves every blood colour and drying state.
 * The PNG is generated by {@code tools/GenerateTextures.java}.
 *
 * <p>Tiles 0-9 are the smooth "realistic" set, tiles 10-15 the blocky pixel-art "redstone" set. The tile
 * helpers below pick from the set chosen by {@link GoreConfig#bloodStyle}.
 */
public final class BloodTextures {
	public static final Identifier ATLAS = Identifier.fromNamespaceAndPath("fluidgore", "textures/misc/blood.png");

	public static final int SPLAT_0 = 0;
	public static final int SPLAT_COUNT = 4;
	public static final int PUDDLE = 4;
	public static final int POOL = 5;
	public static final int DROPLET = 6;
	public static final int FOOTPRINT = 7;
	public static final int STREAK = 8;
	public static final int SMALL_SPLAT = 9;
	public static final int PIXEL_SPLAT_0 = 10;
	public static final int PIXEL_SPLAT_COUNT = 4;
	public static final int PIXEL_PUDDLE = 14;
	public static final int PIXEL_DROPLET = 15;

	private static final int GRID = 4;
	/** Half a texel of inset so neighbouring tiles never bleed in. */
	private static final float INSET = 0.5F / 256.0F;

	private BloodTextures() {
	}

	public static float u0(int tile) {
		return (tile % GRID) / (float) GRID + INSET;
	}

	public static float v0(int tile) {
		return (tile / GRID) / (float) GRID + INSET;
	}

	public static float span() {
		return 1.0F / GRID - 2.0F * INSET;
	}

	private static boolean pixel(RandomSource random) {
		BloodStyle style = GoreConfig.get().bloodStyle;
		return style == BloodStyle.REDSTONE || (style == BloodStyle.MIXED && random.nextBoolean());
	}

	/** A random splat in the configured style. */
	public static int splat(RandomSource random) {
		return pixel(random)
				? PIXEL_SPLAT_0 + random.nextInt(PIXEL_SPLAT_COUNT)
				: SPLAT_0 + random.nextInt(SPLAT_COUNT);
	}

	/** A splat for a small amount of blood. */
	public static int smallSplat(RandomSource random) {
		return pixel(random) ? PIXEL_SPLAT_0 + random.nextInt(PIXEL_SPLAT_COUNT) : SMALL_SPLAT;
	}

	/** Puddle tile; deterministic per puddle (by its serial) so it does not flicker between styles in Mixed. */
	public static int puddle(long serial) {
		BloodStyle style = GoreConfig.get().bloodStyle;
		boolean pixel = style == BloodStyle.REDSTONE || (style == BloodStyle.MIXED && (serial & 8) != 0);
		return pixel ? PIXEL_PUDDLE : PUDDLE;
	}

	public static int droplet() {
		return GoreConfig.get().bloodStyle == BloodStyle.REALISTIC ? DROPLET : PIXEL_DROPLET;
	}
}
